-- Trainings table for portal-editable training catalog
CREATE TABLE IF NOT EXISTS trainings (
  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  category text NOT NULL,
  category_tagline text NOT NULL DEFAULT '',
  name text NOT NULL,
  location text NOT NULL DEFAULT '',
  duration text NOT NULL DEFAULT '',
  overview text NOT NULL DEFAULT '',
  what_you_do text[] NOT NULL DEFAULT '{}',
  what_you_earn text[] NOT NULL DEFAULT '{}',
  who_its_for text NOT NULL DEFAULT '',
  sort_order integer NOT NULL DEFAULT 0,
  category_sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz DEFAULT now()
);

ALTER TABLE trainings ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can read trainings"
  ON trainings FOR SELECT USING (true);

CREATE POLICY "Officers can modify trainings"
  ON trainings FOR ALL USING (
    EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'officer')
  );

-- Seed with existing catalog data
INSERT INTO trainings (category, category_tagline, name, location, duration, overview, what_you_do, what_you_earn, who_its_for, sort_order, category_sort_order) VALUES
('Medical & Life Safety', 'Save lives. Earn certifications that follow you forever.', 'Emergency Medical Technician (EMT)', 'Various military installations', '10 days', 'One of the most demanding and rewarding trainings in the catalog. Cadets complete EMT-Basic certification alongside active-duty medical personnel, learning to assess and treat trauma, manage airways, and respond under pressure.', ARRAY['Patient assessment and triage','Trauma care and wound management','Airway management and oxygen therapy','Practical skills testing under evaluation'], ARRAY['EMT-Basic certification (nationally recognized)','NSCC Medical rating','Community service hours'], 'NSCC cadets interested in medicine, nursing, paramedics, or military healthcare. Physically and mentally demanding.', 0, 0),
('Medical & Life Safety', 'Save lives. Earn certifications that follow you forever.', 'First Responder', 'Naval Medical Center, Portsmouth VA', '7 days', 'Cadets train as First Responders, learning to stabilize patients, manage emergencies, and work within a medical response team. Less intensive than EMT but still rigorous and certified.', ARRAY['Emergency scene management','Patient stabilization and vital signs','CPR/AED certification','Simulated mass casualty events'], ARRAY['First Responder certification','CPR/AED certification'], 'Cadets who want medical training with a slightly lower certification bar than full EMT.', 1, 0),
('Aviation', 'Get off the ground. FAA certifications. Real aircraft.', 'FAA Private Pilot Ground School', 'NAS Pensacola, FL / Various', '7-10 days', 'Cadets receive instruction equivalent to FAA Private Pilot Ground School: aerodynamics, navigation, meteorology, regulations, and flight planning. Instruction is delivered by military aviators and civilian instructors.', ARRAY['Aerodynamics and aircraft systems','FAA regulations and airspace','Weather interpretation and flight planning','Navigation and cross-country planning'], ARRAY['FAA Ground School completion certificate','NSCC Aviation rating','Credit toward FAA Knowledge Test'], 'Any cadet with an interest in aviation, aerospace engineering, or military flight programs. Academically rigorous.', 0, 1),
('Aviation', 'Get off the ground. FAA certifications. Real aircraft.', 'Air Traffic Control Orientation', 'Various ATC facilities', '7 days', 'An immersive look at how the National Airspace System works from the inside. Cadets tour approach and tower facilities, shadow controllers, and receive instruction on radar, communication, and separation standards.', ARRAY['Tower and TRACON facility tours','Radar simulation exercises','Aviation weather and NOTAM review','Communication procedures'], ARRAY['NSCC Aviation rating','Letter of completion'], 'Cadets interested in aviation careers outside of flying: ATC, aerospace operations, military logistics.', 1, 1),
('SCUBA & Maritime Diving', 'Open water certification. Real dives. Military supervision.', 'SCUBA Open Water Certification', 'Naval Station Key West, FL', '10 days', 'Cadets earn a PADI or equivalent Open Water SCUBA certification through a rigorous course conducted by Navy diving professionals. Pool work, skills demonstrations, and multiple open-water dives are required to pass.', ARRAY['Pool skills (buoyancy, mask clearing, regulator recovery)','Open ocean dives to certification depth','Dive planning and buddy procedures','Equipment inspection and maintenance'], ARRAY['PADI Open Water Diver certification (lifetime)','NSCC Diving rating'], 'Cadets who pass a swim qualification. No prior dive experience needed. Physically demanding.', 0, 2),
('SCUBA & Maritime Diving', 'Open water certification. Real dives. Military supervision.', 'Underwater Navigation', 'Naval Station Key West, FL', '7 days', 'Advanced SCUBA training focused on compass navigation, natural navigation, and search patterns underwater. Requires a prior SCUBA certification.', ARRAY['Compass bearings and reciprocal navigation','Natural reference navigation','Underwater search patterns','Night dive procedures'], ARRAY['PADI Underwater Navigation certification','NSCC Advanced Diving rating'], 'Cadets who already hold Open Water SCUBA certification.', 1, 2),
('Special Operations', 'Land navigation. Rappelling. Survival skills. The hard stuff.', 'Rappelling & Vertical Assault', 'Fort Devens, MA / Ft. Jackson, SC', '7 days', 'Cadets learn to rappel from towers and natural terrain, conduct vertical movement in a tactical context, and work as a team under physical stress. Instruction is led by Army Rangers and Special Forces personnel.', ARRAY['Rappelling from towers up to 50 feet','Rope handling and knot tying','Team movement on vertical terrain','Physical conditioning under instruction'], ARRAY['NSCC Special Operations rating','Rappelling completion certificate'], 'Physically fit cadets looking for the hardest training in the catalog. Strong PT baseline recommended.', 0, 3),
('Special Operations', 'Land navigation. Rappelling. Survival skills. The hard stuff.', 'SERE (Survival, Evasion, Resistance, Escape)', 'Various mountain/wilderness installations', '7-10 days', 'A serious program that teaches cadets how to survive in austere environments. Covers food procurement, shelter construction, navigation without equipment, and resistance to stress.', ARRAY['Fire starting, shelter construction, water procurement','Land navigation without GPS','Stress inoculation and decision-making under pressure','Field exercises in realistic scenarios'], ARRAY['NSCC SERE rating','Wilderness survival skills documentation'], 'Mature cadets with strong physical conditioning. Mentally demanding as much as physically.', 1, 3),
('STEM & Technology', 'Engineering. Cyber. Nuclear propulsion. The future of the fleet.', 'Cybersecurity Operations', 'NSA / Various DoD facilities', '7 days', 'Cadets receive instruction in offensive and defensive cybersecurity fundamentals from DoD personnel. Topics include network security, threat analysis, and basic penetration testing concepts.', ARRAY['Network architecture and threat vectors','Hands-on CTF (capture the flag) exercises','Security operations center (SOC) simulation','Cryptography basics'], ARRAY['NSCC STEM rating','Introduction to cybersecurity certification'], 'Cadets with some computer science background or a strong interest in technology and security careers.', 0, 4),
('STEM & Technology', 'Engineering. Cyber. Nuclear propulsion. The future of the fleet.', 'Naval Nuclear Propulsion', 'Naval Nuclear Power School, Goose Creek, SC', '7 days', 'A rare look inside one of the most technically demanding fields in the Navy. Cadets receive instruction in nuclear physics, reactor operations, and the engineering systems that power submarines and aircraft carriers.', ARRAY['Nuclear physics and reactor theory','Propulsion plant systems overview','Safety procedures and engineering watch-standing','Tours of training reactors'], ARRAY['NSCC Nuclear rating','Letter of completion from Naval Nuclear Power School'], 'Strong STEM students, particularly those interested in Navy nuclear officer or enlisted programs.', 1, 4),
('Seamanship & Navigation', 'Underway aboard Navy vessels. Real charts. Real water.', 'Deck Operations & Seamanship', 'Various Naval stations', '7 days', 'Cadets spend time aboard Navy vessels learning the fundamentals of deck seamanship: line handling, watch-standing, navigation plotting, and ship handling basics. One of the most hands-on trainings in the catalog.', ARRAY['Line handling and marlinespike seamanship','Chart navigation and piloting','Underway watch-standing rotations','Rules of the Road (maritime collision regulations)'], ARRAY['NSCC Seamanship rating','Small Boat handling qualification'], 'Any cadet. Strongly recommended for those considering Navy or Coast Guard service.', 0, 5),
('Leadership & Officer Development', 'For cadets ready to lead. Command courses and staff billets.', 'Junior Officer Leadership Course', 'NSCC National Headquarters', '10 days', 'For senior cadets on track for officer-level billets. An intensive leadership curriculum covering command philosophy, cadet welfare, staff organization, training design, and mentorship.', ARRAY['Leadership philosophy and case studies','Staff planning and operations order writing','Training design and instruction delivery','Peer evaluation and self-assessment'], ARRAY['NSCC Officer Candidate certification','Eligibility for Officer-track billet assignment'], 'PO2 and above cadets with demonstrated leadership record. Command recommendation typically required.', 0, 6),
('Arts, Music & Culture', 'The marching band. Color guard. Journalism. Film.', 'Marching Band & Drum Corps', 'Various venues and camps', '7-10 days', 'Cadets with musical backgrounds join an ensemble that performs at military and civic events. Instruction covers ensemble performance, marching fundamentals, and musical discipline.', ARRAY['Daily ensemble rehearsals and sectionals','Marching fundamentals and drill design','Performance at military ceremonies','Music theory and sight-reading'], ARRAY['NSCC Music rating','Performance experience and ensemble membership'], 'Cadets with prior instrument or drumline experience.', 0, 7),
('Arts, Music & Culture', 'The marching band. Color guard. Journalism. Film.', 'Journalism & Photography', 'Various media facilities', '7 days', 'Cadets train as public affairs journalists and photographers alongside military PA specialists. They produce written and photo content that may be published through official NSCC channels.', ARRAY['News writing and AP style fundamentals','Photography composition and lighting','Interview techniques and source ethics','Photo editing and publication workflow'], ARRAY['NSCC Journalism rating','Published work in NSCC media outlets'], 'Cadets interested in media, communications, public relations, or photography.', 1, 7);
